package com.raglatest.backend.support;

import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import java.io.IOException;
import java.sql.Connection;
import java.sql.SQLException;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.test.context.DynamicPropertyRegistry;

/**
 * 默认测试套件的真实 Postgres。
 *
 * <p>为什么不是 H2/SQLite 兼容模式：迁移脚本与查询是 Postgres 方言（timestamptz、
 * ON CONFLICT、GENERATED BY IDENTITY、多值 INSERT），用别的引擎测等于测了另一个系统。</p>
 *
 * <p>为什么不是 Testcontainers：mvnw test 必须零外部依赖（见
 * src/test/resources/application.yml 的说明），而 Docker 守护进程在开发机上
 * 并不总是运行。Zonky 的嵌入式实现解压官方二进制后本地 initdb，纯进程内，
 * 因此默认套件能保持"不装任何东西也能跑"。需要真容器（Redis/RabbitMQ）的用例
 * 仍在 *IT 里走 Testcontainers。</p>
 *
 * <p>每个测试类一个库：Postgres 实例按 JVM 起一次（约 1 秒），库名由调用方给，
 * 避免类之间靠"记得清理数据"互相妥协。</p>
 */
public final class EmbeddedPostgresSupport {

    private static final Set<String> PREPARED_DATABASES = ConcurrentHashMap.newKeySet();
    private static EmbeddedPostgres postgres;

    private EmbeddedPostgresSupport() {
    }

    public static synchronized void register(DynamicPropertyRegistry registry, String databaseName) {
        EmbeddedPostgres instance = instance();
        if (PREPARED_DATABASES.add(databaseName)) {
            createDatabase(instance, databaseName);
        }
        registry.add("spring.datasource.url", () -> instance.getJdbcUrl("postgres", databaseName));
        registry.add("spring.datasource.username", () -> "postgres");
        registry.add("spring.datasource.password", () -> "");
        registry.add("spring.datasource.driver-class-name", () -> "org.postgresql.Driver");
    }

    private static synchronized EmbeddedPostgres instance() {
        if (postgres == null) {
            try {
                postgres = EmbeddedPostgres.start();
            } catch (IOException ex) {
                throw new IllegalStateException(
                        "无法启动嵌入式 Postgres（测试库）：" + ex.getMessage(), ex);
            }
            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                try {
                    postgres.close();
                } catch (IOException ignored) {
                    // JVM 退出中：关不掉就交给操作系统回收
                }
            }));
        }
        return postgres;
    }

    /**
     * 建库。zonky 2.x 的 {@code getDatabase(user, db)} 只返回数据源，并不负责创建
     * （初始只有 postgres 一个库），所以这里连到 postgres 库显式 CREATE DATABASE。
     */
    private static void createDatabase(EmbeddedPostgres instance, String databaseName) {
        try (Connection admin = instance.getPostgresDatabase().getConnection();
             java.sql.Statement statement = admin.createStatement()) {
            statement.execute("CREATE DATABASE \"" + databaseName + "\"");
        } catch (SQLException ex) {
            // 42P04 = duplicate_database：同一 JVM 内重复注册同名库时幂等放过。
            if (!"42P04".equals(ex.getSQLState())) {
                throw new IllegalStateException(
                        "无法创建测试库 " + databaseName + "：" + ex.getMessage(), ex);
            }
        }
    }
}
